import torch

def run(q, k, v, scale, is_causal, enable_gqa):
    return torch.nn.functional.scaled_dot_product_attention(q, k, v, attn_mask=None, scale=scale, is_causal=is_causal, enable_gqa=enable_gqa)

def _dtype_from_context(ctx, name):
    return getattr(torch, ctx[f"{name}__dtype"])

def gen_inputs(ctx, device):
    result = {}
    for name in ("q", "k", "v"):
        result[name] = torch.empty(
            ctx[f"{name}__shape"],
            dtype=_dtype_from_context(ctx, name),
            device=device,
        ).uniform_(-0.05, 0.05)
    return result
